## 3. 🧪 Unit Test: useWritingTool Hook

Test the React hook using React Testing Library:

```typescript
// src/modules/ai/adapters/hooks/writing-tools/__tests__/use-writing-tool.test.tsx

import 'reflect-metadata';
import { renderHook, act } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { useWritingTool } from '../use-writing-tool';
import { Result } from '@/infrastructure/utils/result';
import React from 'react';

// Mock the API client resolved from DI
jest.mock('@/infrastructure/di/container', () => ({
  container: {
    resolve: jest.fn(() => ({
      executeToolApi: jest.fn().mockResolvedValue(
        Result.ok({ summarizedText: 'Summary result' })
      ),
    })),
  },
}));

// Mock AuthContext
jest.mock('@/context/AuthContext', () => ({
  useAuth: () => ({
    user: { uid: 'test-user' },
    updateUsage: jest.fn(),
  }),
}));

const wrapper = ({ children }: { children: React.ReactNode }) => (
  <QueryClientProvider client={new QueryClient()}>
    {children}
  </QueryClientProvider>
);

describe('useWritingTool', () => {
  it('calls the API and returns result', async () => {
    const { result } = renderHook(
      () => useWritingTool('summarize'),
      { wrapper }
    );

    await act(async () => {
      await result.current.execute({ text: 'Long article text...' });
    });

    expect(result.current.data).toEqual({ summarizedText: 'Summary result' });
    expect(result.current.isError).toBe(false);
  });

  it('surfaces errors from the API', async () => {
    jest.mock('@/infrastructure/di/container', () => ({
      container: {
        resolve: jest.fn(() => ({
          executeToolApi: jest.fn().mockResolvedValue(
            Result.fail({ message: 'Insufficient credits' })
          ),
        })),
      },
    }));

    const { result } = renderHook(
      () => useWritingTool('summarize'),
      { wrapper }
    );

    await act(async () => {
      await result.current.execute({ text: 'text' });
    });

    expect(result.current.isError).toBe(true);
  });
});
```

---

## 4. 🌐 Integration Test: API Route (HTTP-level)

Test the full request/response cycle for `POST /api/writing-tools/[tool]`:

```typescript
// src/app/api/writing-tools/__tests__/route.integration.test.ts

import { POST } from '../[tool]/route';
import { NextRequest } from 'next/server';

// Mock the DI container and controller
jest.mock('@/infrastructure/di/container', () => ({
  container: {
    resolve: jest.fn(() => ({
      runTool: jest.fn().mockResolvedValue(
        // Return a Result.ok with mocked data
        { isSuccess: true, getValue: () => ({ summarizedText: 'Test summary' }) }
      ),
    })),
  },
}));

function makeRequest(toolName: string, body: object): NextRequest {
  return new NextRequest(
    `http://localhost:3000/api/writing-tools/${toolName}`,
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    }
  );
}

describe('POST /api/writing-tools/[tool]', () => {
  it('returns 200 with AI output for valid input', async () => {
    const req = makeRequest('summarize', {
      text: 'A long piece of text to summarize.',
      language: 'en',
    });

    const response = await POST(req, { params: { tool: 'summarize' } });
    const data = await response.json();

    expect(response.status).toBe(200);
    expect(data).toHaveProperty('summarizedText');
  });

  it('returns 400 for invalid input schema', async () => {
    const req = makeRequest('summarize', { text: '' }); // empty text fails validation

    const response = await POST(req, { params: { tool: 'summarize' } });

    expect(response.status).toBe(400);
  });

  it('returns 404 for unknown tool', async () => {
    const req = makeRequest('unknown-tool', { text: 'Hello' });

    const response = await POST(req, { params: { tool: 'unknown-tool' } });

    expect(response.status).toBe(404);
  });
});
```

---

## 5. 🚀 Running the Tests

```bash
# Run all AI-related tests
npm test -- --testPathPattern="modules/ai"

# Run only flow tests
npm test -- --testPathPattern="flows/__tests__"

# Run a specific test file
npm test -- --testPathPattern="summarize-text"

# Run with coverage
npm test -- --coverage --testPathPattern="modules/ai"

# Type-check before testing (always do this first!)
npm run typecheck && npm test
```

---

## 6. 📋 Quick Reference: What to Mock Per Test Level

| Layer | What to Mock |
|-------|-------------|
| **Flow tests** | `Genkit.ts` (`ai.defineFlow`, `ai.definePrompt`) |
| **UseCase tests** | All injected repositories + `IAiService` |
| **Hook tests** | `container.resolve()` → API client, `useAuth()` |
| **Route tests** | `container.resolve()` → `AiController` |

---

## 7. 💡 Tips Specific to This Codebase

- **Always import `reflect-metadata`** at the top of test files that use tsyringe DI classes
- **Use `Result.ok(...)` / `Result.fail(...)`** when mocking service returns — never raw values
- **Call `.getValue()`** (not `.value`) when unwrapping a success Result
- **Guest tool access**: To test guest flows, set `user: null` and ensure the tool has `isFreeForGuests: true` in registry
- **Credit refund test**: Set `mockAiService.runFlow` to return `Result.fail(...)` and assert `mockCreditRepo.refund` was called

